"""
Corelation report preparation tool.

Step 1: For every PDMerged folder found under the input folder(s), open the
        .grltrace files of TEST.PD.PHY.ALL.1 .. TEST.PD.PHY.ALL.5 and delete
        'testresult.deb' from inside the archive.
Step 2: Delete the PDF and CSV report files (run folder + PDMerged folder,
        top level only - test-case sub folders are not touched).
Step 3: In PDMerged\\PD_Merged.xml, replace the <test> blocks of
        TEST.PD.PHY.ALL.1 .. TEST.PD.PHY.ALL.3 with the ones from the C2 EPR
        run's PD_Merged.xml, keeping the target's own non-empty check
        comments (packet numbers). A backup (PD_Merged.xml.bak) is written first.

Usage:
    python corelation.py "D:\\Corelation\\VDPWR_EPR" --c2 "D:\\Corelation\\C2_EPR"
    python corelation.py "<folder1>" "<folder2>" --c2 "<c2 folder>" --dry-run
    python corelation.py "<folder>" --steps 1,2      # only steps 1 and 2
"""

import argparse
import os
import re
import shutil
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

PHY_TEST_CASES = [f"TEST.PD.PHY.ALL.{i}" for i in range(1, 6)]
XML_TEST_CASES = [f"TEST.PD.PHY.ALL.{i}" for i in range(1, 4)]
MERGED_XML = "PD_Merged.xml"
ENTRY_TO_DELETE = "testresult.deb"
REPORT_EXTENSIONS = {".pdf", ".csv"}

SEVEN_ZIP_CANDIDATES = [
    r"C:\Program Files\7-Zip\7z.exe",
    r"C:\Program Files (x86)\7-Zip\7z.exe",
]


def find_7zip():
    for path in SEVEN_ZIP_CANDIDATES:
        if os.path.isfile(path):
            return path
    return shutil.which("7z")


def find_pdmerged_folders(root: Path):
    """Return every folder named PDMerged under root (or root itself)."""
    if root.name.lower() == "pdmerged":
        return [root]
    return sorted(p for p in root.rglob("PDMerged") if p.is_dir())


# ---------------------------------------------------------------- Step 1
def archive_entries(trace: Path):
    with zipfile.ZipFile(trace) as zf:
        return zf.namelist()


def delete_entry_with_7zip(seven_zip: str, trace: Path, entry: str):
    result = subprocess.run(
        [seven_zip, "d", str(trace), entry, "-y"],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stdout + result.stderr)


def delete_entry_with_python(trace: Path, entry: str):
    """Rewrite the zip without the entry (fallback when 7-Zip is missing)."""
    fd, tmp_name = tempfile.mkstemp(suffix=".grltrace", dir=trace.parent)
    os.close(fd)
    try:
        with zipfile.ZipFile(trace) as src, \
                zipfile.ZipFile(tmp_name, "w", zipfile.ZIP_DEFLATED) as dst:
            for item in src.infolist():
                if item.filename.lower() != entry.lower():
                    dst.writestr(item, src.read(item.filename))
        os.replace(tmp_name, trace)
    finally:
        if os.path.exists(tmp_name):
            os.remove(tmp_name)


def step1_remove_testresult(pdmerged: Path, seven_zip, dry_run: bool):
    print(f"\n[Step 1] {pdmerged}")
    for case in PHY_TEST_CASES:
        case_dir = pdmerged / case
        if not case_dir.is_dir():
            print(f"  {case}: folder not found - skipped")
            continue
        traces = sorted(case_dir.glob("*.grltrace"))
        if not traces:
            print(f"  {case}: no .grltrace file - skipped")
            continue
        for trace in traces:
            try:
                entries = archive_entries(trace)
            except zipfile.BadZipFile:
                print(f"  {trace.name}: not a valid archive - skipped")
                continue
            match = next((e for e in entries
                          if e.lower() == ENTRY_TO_DELETE), None)
            if match is None:
                print(f"  {trace.name}: {ENTRY_TO_DELETE} not present - nothing to do")
                continue
            if dry_run:
                print(f"  {trace.name}: would delete {match}")
                continue
            if seven_zip:
                delete_entry_with_7zip(seven_zip, trace, match)
            else:
                delete_entry_with_python(trace, match)
            print(f"  {trace.name}: deleted {match}")


# ---------------------------------------------------------------- Step 2
def step2_delete_reports(pdmerged: Path, dry_run: bool):
    run_folder = pdmerged.parent
    print(f"\n[Step 2] {run_folder}")
    found = False
    for folder in (run_folder, pdmerged):
        for f in sorted(folder.iterdir()):
            if f.is_file() and f.suffix.lower() in REPORT_EXTENSIONS:
                found = True
                rel = f.relative_to(run_folder)
                if dry_run:
                    print(f"  would delete {rel}")
                else:
                    f.unlink()
                    print(f"  deleted {rel}")
    if not found:
        print("  no PDF/CSV files found")


# ---------------------------------------------------------------- Step 3
def read_text(path: Path) -> str:
    # newline="" keeps the original line endings untouched
    with open(path, "r", encoding="utf-8", newline="") as f:
        return f.read()


def write_text(path: Path, text: str):
    with open(path, "w", encoding="utf-8", newline="") as f:
        f.write(text)


def test_block_pattern(tc_id: str):
    # <test> elements are not nested, so the first </test> closes the block
    return re.compile(r'<test tcID="' + re.escape(tc_id) + r'">.*?</test>',
                      re.DOTALL)


def block_scores(block: str):
    return [s.strip() for s in re.findall(r'<score value="([^"]*)"', block)]


CHECK_RE = re.compile(r'(<check checkID="([^"]+)">.*?<comment>)(.*?)(</comment>)',
                      re.DOTALL)


def keep_target_comments(c2_block: str, target_block: str) -> str:
    """Use the C2 block but keep the target's non-empty check comments
    (e.g. its own Packet numbers)."""
    target_comments = {m.group(2): m.group(3) for m in CHECK_RE.finditer(target_block)
                       if m.group(3).strip()}

    def repl(m):
        comment = target_comments.get(m.group(2), m.group(3))
        return m.group(1) + comment + m.group(4)

    return CHECK_RE.sub(repl, c2_block)


def find_c2_xml(c2_path: Path) -> Path:
    if c2_path.is_file():
        return c2_path
    if c2_path.name.lower() == "pdmerged":
        candidates = [c2_path / MERGED_XML]
    else:
        candidates = sorted(c2_path.rglob(f"PDMerged/{MERGED_XML}"))
    candidates = [c for c in candidates if c.is_file()]
    if len(candidates) != 1:
        raise ValueError(f"Expected exactly one PDMerged\\{MERGED_XML} under "
                         f"{c2_path}, found {len(candidates)}: {candidates}")
    return candidates[0]


def step3_copy_c2_results(pdmerged: Path, c2_xml: Path, dry_run: bool):
    target = pdmerged / MERGED_XML
    print(f"\n[Step 3] {target}")
    print(f"  source (C2 EPR): {c2_xml}")
    if not target.is_file():
        print(f"  {MERGED_XML} not found - skipped")
        return
    if target.resolve() == c2_xml.resolve():
        print("  target is the C2 EPR file itself - skipped")
        return

    source_text = read_text(c2_xml)
    text = read_text(target)
    changed = False
    for tc in XML_TEST_CASES:
        pattern = test_block_pattern(tc)
        src = pattern.search(source_text)
        dst = pattern.search(text)
        if not src:
            print(f"  {tc}: not in C2 EPR xml - skipped")
            continue
        if not dst:
            print(f"  {tc}: not in target xml - skipped")
            continue
        new_block = keep_target_comments(src.group(0), dst.group(0))
        if new_block == dst.group(0):
            print(f"  {tc}: already done")
            continue
        old, new = block_scores(dst.group(0)), block_scores(new_block)
        print(f"  {tc}: {old} -> {new}")
        text = text[:dst.start()] + new_block + text[dst.end():]
        changed = True

    if changed and not dry_run:
        backup = target.with_name(target.name + ".bak")
        if not backup.exists():  # keep the very first original
            shutil.copy2(target, backup)
            print(f"  backup: {backup.name}")
        write_text(target, text)
        print("  saved")


# ---------------------------------------------------------------- main
def main():
    parser = argparse.ArgumentParser(description="Corelation report preparation")
    parser.add_argument("folders", nargs="*",
                        help="Input folder(s); every PDMerged folder below is processed")
    parser.add_argument("--steps", default="1,2,3",
                        help="Comma separated steps to run (default: 1,2,3)")
    parser.add_argument("--c2",
                        help="C2 EPR run folder (or its PD_Merged.xml) used by step 3")
    parser.add_argument("--dry-run", action="store_true",
                        help="Only show what would be changed")
    args = parser.parse_args()

    folders = args.folders
    if not folders:
        entered = input("Enter input folder path(s), separated by ';': ").strip()
        folders = [f.strip().strip('"') for f in entered.split(";") if f.strip()]
    if not folders:
        sys.exit("No input folder given.")

    steps = {s.strip() for s in args.steps.split(",")}

    c2 = None
    if "3" in steps:
        c2 = args.c2 or input("Enter C2 EPR folder path: ").strip().strip('"')
        if not c2:
            sys.exit("Step 3 needs the C2 EPR folder (--c2).")
    try:
        process(folders, c2, steps, args.dry_run)
    except ValueError as e:
        sys.exit(str(e))


def process(folders, c2, steps, dry_run=False):
    """Run the selected steps on every PDMerged folder under `folders`."""
    c2_xml = c2_root = None
    if "3" in steps:
        c2_xml = find_c2_xml(Path(c2))
        c2_root = c2_xml.parent.parent

    seven_zip = find_7zip()
    if "1" in steps:
        print(f"Using {'7-Zip: ' + seven_zip if seven_zip else 'Python zipfile (7-Zip not found)'}")

    for folder in folders:
        root = Path(folder)
        if not root.is_dir():
            print(f"\nFolder not found: {root}")
            continue
        pdmerged_list = find_pdmerged_folders(root)
        if not pdmerged_list:
            print(f"\nNo PDMerged folder under: {root}")
            continue
        for pdmerged in pdmerged_list:
            if c2_xml and pdmerged.parent == c2_root:
                print(f"\nSkipping C2 EPR source run: {pdmerged}")
                continue
            if "1" in steps:
                step1_remove_testresult(pdmerged, seven_zip, dry_run)
            if "2" in steps:
                step2_delete_reports(pdmerged, dry_run)
            if "3" in steps:
                step3_copy_c2_results(pdmerged, c2_xml, dry_run)

    print("\nDone." + (" (dry run - nothing changed)" if dry_run else ""))


if __name__ == "__main__":
    main()

