    if not m:
        return None
    end = text.find("</table>", m.end())
    rows = []
    for tr in TR_RE.findall(text[m.end():end]):
        cells = [cell_text(td) for td in TD_RE.findall(tr)]
        if len(cells) >= 5 and cells[0].isdigit():
            rows.append((cells[1], cells[4]))  # start/stop packet numbers differ per run
    return rows


def step5_check_ams(pdmerged: Path, c2_pdmerged: Path, dry_run=False, log=print):
    log(f"\n[Step 5] {pdmerged}")
    ams_files = sorted(pdmerged.glob(AMS_GLOB))
    if not ams_files:
        log("  no AMS HTML file - nothing to check")
        return
    mismatch, unchecked = [], []
    for tc in XML_TEST_CASES:
        mine = pdmerged / tc / f"{tc}.html"
        ref = c2_pdmerged / tc / f"{tc}.html"
        a = ams_summary(mine) if mine.is_file() else None
        b = ams_summary(ref) if ref.is_file() else None
        if a is None or b is None:
            unchecked.append(tc)
            log(f"  {tc}: AMS summary not found - not checked")
        elif a == b:
            log(f"  {tc}: AMS matches C2 EPR ({len(a)} AMS)")
        else:
            mismatch.append(tc)
            log(f"  {tc}: AMS differs from C2 EPR")
            for i in range(max(len(a), len(b))):
                x = a[i] if i < len(a) else "-"
                y = b[i] if i < len(b) else "-"
                if x != y:
                    log(f"      #{i}: VD PWR {x}  vs  C2 {y}")
    if not mismatch:
        log("  AMS HTML kept" + (" (some tests could not be checked)" if unchecked else ""))
        return
    for f in ams_files:
        if dry_run:
            log(f"  would delete {f.name}")
        else:
            f.unlink()
            log(f"  deleted {f.name}")


