def step5_check_ams(pdmerged: Path, c2_pdmerged: Path, dry_run=False, log=print):
    log(f"\n[Step 5] {pdmerged}")
    ams_files = sorted(pdmerged.glob(AMS_GLOB))
    if not ams_files:
        log("  no AMS HTML file - nothing to check")
        return
    c2_files = sorted(c2_pdmerged.glob(AMS_GLOB))
    if not c2_files:
        log("  no AMS HTML in C2 EPR - not checked, AMS HTML kept")
        return
    mine_groups = ams_groups(ams_files[0])
    c2_groups = ams_groups(c2_files[0])
    log(f"  {ams_files[0].name} vs C2 {c2_files[0].name}")
    if mine_groups is None or c2_groups is None:
        log("  AMS Summary table not found - not checked, AMS HTML kept")
        return
    mismatch = []
    for i, tc in enumerate(XML_TEST_CASES):  # first 3 groups = PHY.ALL.1..3
        a = mine_groups[i] if i < len(mine_groups) else None
        b = c2_groups[i] if i < len(c2_groups) else None
        if a is None or b is None:
            mismatch.append(tc)
            log(f"  {tc}: AMS group missing - treated as mismatch")
        elif a == b:
            log(f"  {tc}: AMS matches C2 EPR ({len(a)} AMS)")
        else:
            mismatch.append(tc)
            log(f"  {tc}: AMS differs from C2 EPR")
            for i in range(max(len(a), len(b))):
                x = a[i] if i < len(a) else "-"
                y = b[i] if i < len(b) else "-"
                if x != y:
                    log(f"      #{i}: VD PWR {x}  vs  C2 {y}")
    if not mismatch:
        log("  AMS matches C2 EPR - AMS HTML kept")
        return
    for f in ams_files:
        if dry_run:
            log(f"  would delete {f.name}")
        else:
            f.unlink()
            log(f"  deleted {f.name}")


