# ---------------------------------------------------------------- Step 5
def ams_groups(path: Path):
    """AMS Summary table of an AMS_Run_*.html, split per test case.
    The table lists one group per test, in test order; each group restarts at
    AMS Index 0. Returns [[(AMS name, AMS status), ...], ...]."""
    text = read_text(path)
    m = AMS_HEADING_RE.search(text)
    if not m:
        return None
    end = text.find("</table>", m.end())
    groups = []
    for tr in TR_RE.findall(text[m.end():end]):
        cells = [cell_text(td) for td in TD_RE.findall(tr)]
        if len(cells) < 5 or not cells[0].isdigit():
            continue
        if cells[0] == "0" or not groups:
            groups.append([])
        groups[-1].append((cells[1], cells[4]))  # start/stop packet numbers differ per run
    return groups


def test_ams(pdmerged: Path) -> dict:
    """{test id: AMS rows} from each test folder's own HTML
    (AMS_Run_*.html has no test names, the per-test HTML has)."""
    out = {}
    for d in pdmerged.iterdir():
        page = d / f"{d.name}.html"
        if d.is_dir() and page.is_file():
            groups = ams_groups(page)
            out[d.name] = groups[0] if groups else []
    return out


def log_ams_differences(pdmerged: Path, c2_pdmerged: Path, log):
    """Name the test cases whose AMS differ, for the log only."""
    mine, ref = test_ams(pdmerged), test_ams(c2_pdmerged)
    for tc in sorted(mine.keys() | ref.keys()):
        if tc not in ref:
            log(f"    {tc}: not in C2 EPR")
        elif tc not in mine:
            log(f"    {tc}: only in C2 EPR")
        elif mine[tc] != ref[tc]:
            a, b = mine[tc], ref[tc]
            i = next((k for k, (x, y) in enumerate(zip(a, b)) if x != y), min(len(a), len(b)))
            x = a[i] if i < len(a) else "-"
            y = b[i] if i < len(b) else "-"
